  "邮箱接入": { zh: "邮箱接入", en: "Mail Accounts" },
  "接入 IMAP 邮箱后，把指定发件人的邮件自动转成订阅文章：每个白名单发件人生成一条订阅源，正文在阅读器内干净呈现。密码经系统加密（DPAPI）只保存在本机，最多 3 个账户。": { zh: "接入 IMAP 邮箱后，把指定发件人的邮件自动转成订阅文章：每个白名单发件人生成一条订阅源，正文在阅读器内干净呈现。密码经系统加密（DPAPI）只保存在本机，最多 3 个账户。", en: "Connect an IMAP mailbox and turn mail from chosen senders into subscriptions: each whitelisted sender becomes a feed, rendered cleanly in the reader. Passwords are OS-encrypted (DPAPI) and never leave this machine. Up to 3 accounts." },
