  "还没有邮箱账户。常见邮箱（QQ / 163 / Gmail / Outlook）需在邮箱网页设置里开启 IMAP 并使用授权码或应用专用密码。": { zh: "还没有邮箱账户。常见邮箱（QQ / 163 / Gmail / Outlook）需在邮箱网页设置里开启 IMAP 并使用授权码或应用专用密码。", en: "No mailbox yet. Common providers (QQ / 163 / Gmail / Outlook) require enabling IMAP in web settings and using an auth code or app password." },
