  "C 翻译 · V 摘要 · B 上一篇 · N 下一篇 · M 收藏": { zh: "C 翻译 · V 摘要 · B 上一篇 · N 下一篇 · M 收藏", en: "C Translate · V Summary · B Previous · N Next · M Star" },
  "DeepSeek 会按此选项发送 thinking；选择低、中、高时也会发送对应的 reasoning_effort。": { zh: "DeepSeek 会按此选项发送 thinking；选择低、中、高时也会发送对应的 reasoning_effort。", en: "DeepSeek sends thinking according to this setting. Low, Medium, and High also send the corresponding reasoning_effort." },
  "DeepSeek 推荐配置": { zh: "DeepSeek 推荐配置", en: "Recommended DeepSeek Settings" },
  "ESC 退出，按下 Ctrl+/ 查看快捷键": { zh: "ESC 退出，按下 Ctrl+/ 查看快捷键", en: "Press ESC to exit, Ctrl+/ for shortcuts" },
  "deepseek-v4-flash（推荐）": { zh: "deepseek-v4-flash（推荐）", en: "deepseek-v4-flash (Recommended)" },
  "Feed 内容格式不完整。": { zh: "Feed 内容格式不完整。", en: "The feed data is incomplete or malformed." },
  "RobinRead 专为沉浸式阅读打造。在保持纸张排版美感的同时，提供舒适的长文阅读体验。字号调整会同步到所有文章。": { zh: "RobinRead 专为沉浸式阅读打造。在保持纸张排版美感的同时，提供舒适的长文阅读体验。字号调整会同步到所有文章。", en: "RobinRead is built for focused reading, combining paper-inspired typography with a comfortable long-form experience. Text size changes apply to every article." },
  "The Morning Digest · 晨间速览": { zh: "The Morning Digest · 晨间速览", en: "The Morning Digest · Live Preview" },
  "v%@": { zh: "v%@", en: "v%@" },
  "Version %@ (Build %@)": { zh: "Version %1$@ (Build %2$@)", en: "Version %@ (Build %@)" },
  "上下对照": { zh: "上下对照", en: "Bilingual View" },
  "上次同步：%@": { zh: "上次同步：%@", en: "Last synced: %@" },
