  "下载新版本": { zh: "下载新版本", en: "Download Update" },
  "不再提示此版本更新": { zh: "不再提示此版本更新", en: "Do not remind me about this version again" },
  "专为沉浸式阅读打造的现代 RSS 订阅与 AI 强力阅读助手。": { zh: "专为沉浸式阅读打造的现代 RSS 订阅与 AI 强力阅读助手。", en: "A modern RSS reader with powerful AI tools, built for focused reading." },
  "专为沉浸式阅读打造的现代 RSS 订阅与 AI 阅读助手。": { zh: "专为沉浸式阅读打造的现代 RSS 订阅与 AI 阅读助手。", en: "A modern RSS reader with thoughtful AI tools, built for focused reading." },
  "个性化 Prompt": { zh: "个性化 Prompt", en: "Custom Prompt" },
  "中": { zh: "中", en: "Medium" },
  "仅允许 HTTPS；局域网 HTTP 需在设置中明确开启。": { zh: "仅允许 HTTPS；局域网 HTTP 需在设置中明确开启。", en: "HTTPS is required. Local-network HTTP must be explicitly enabled in Settings." },
  "仅在你点按生成后，正文才会发送给模型。": { zh: "仅在你点按生成后，正文才会发送给模型。", en: "Article content is sent to the model only after you click Generate." },
  "仅在服务商明确支持时生效；翻译和划词解释会自动关闭推理。": { zh: "仅在服务商明确支持时生效；翻译和划词解释会自动关闭推理。", en: "Used only when explicitly supported by the provider. Translation and selection explanations disable reasoning automatically." },
  "仅存于本机，不参与同步": { zh: "仅存于本机，不参与同步", en: "Stored only on this PC; never synced" },
  "仅手动": { zh: "仅手动", en: "Manual Only" },
  "仅用于模型 Base URL。HTTP 未加密，只有在你信任局域网环境时才建议开启。": { zh: "仅用于模型 Base URL。HTTP 未加密，只有在你信任局域网环境时才建议开启。", en: "Applies only to the model Base URL. HTTP is unencrypted; enable it only on a trusted local network." },
