  "保存后会立即抓取一次 Feed。RobinRead 只保存订阅地址、文章和阅读状态。": { zh: "保存后会立即抓取一次 Feed。RobinRead 只保存订阅地址、文章和阅读状态。", en: "RobinRead fetches the feed immediately and stores only its URL, articles, and reading state." },
