  "新版本发布后，应用会提示更新；也可随时前往官网下载最新安装包。": { zh: "新版本发布后，应用会提示更新；也可随时前往官网下载最新安装包。", en: "The app notifies you when a new version ships; you can also grab the latest installer from the website anytime." },
  "知更是一款本地优先的纸感阅读器。你的每一条使用反馈都会让纸面更安静、更称手。": { zh: "知更是一款本地优先的纸感阅读器。你的每一条使用反馈都会让纸面更安静、更称手。", en: "RobinRead is a local-first paper-feel reader. Every piece of feedback makes the page quieter and handier." },
  "知更 RobinRead for Windows —— 本地优先、AI 增强的纸感三栏 RSS 阅读器。": { zh: "知更 RobinRead for Windows —— 本地优先、AI 增强的纸感三栏 RSS 阅读器。", en: "RobinRead for Windows — a local-first, AI-enhanced three-pane RSS reader." },
