  "霞鹜文楷（内置）": { zh: "霞鹜文楷（内置）", en: "LXGW WenKai (Built-in)" },
  "霞鹜文楷为内置开源字体（OFL 授权），离线可用，楷体风格适合文艺类长文。": { zh: "霞鹜文楷为内置开源字体（OFL 授权），离线可用，楷体风格适合文艺类长文。", en: "LXGW WenKai is a bundled open-source font (OFL licensed). Works offline; its kai style suits literary long-form reading." },
  "段落风格": { zh: "段落风格", en: "Paragraph Style" },
  "空行式以段间距分段（西式）；缩进式首行空两格、段间不留空（中文书刊惯例）。": { zh: "空行式以段间距分段（西式）；缩进式首行空两格、段间不留空（中文书刊惯例）。", en: "Spaced separates paragraphs with blank space (Western); Indented sets a two-em first line with no gap (Chinese book convention)." },
  "空行式（默认）": { zh: "空行式（默认）", en: "Spaced (Default)" },
  "缩进式": { zh: "缩进式", en: "First-line Indent" },
  "文字对齐": { zh: "文字对齐", en: "Text Alignment" },
  "两端对齐左右边缘齐平，更接近报刊排版；左对齐则行长自然。": { zh: "两端对齐左右边缘齐平，更接近报刊排版；左对齐则行长自然。", en: "Justified lines are flush on both edges, closer to print layout; left-aligned lines keep their natural length." },
  "左对齐（默认）": { zh: "左对齐（默认）", en: "Left (Default)" },
  "两端对齐": { zh: "两端对齐", en: "Justified" },
  "字距": { zh: "字距", en: "Letter Spacing" },
  "在默认字距基础上微调正文字间距；代码块不受影响。": { zh: "在默认字距基础上微调正文字间距；代码块不受影响。", en: "Fine-tune body letter spacing on top of the default; code blocks are unaffected." },
  "微宽": { zh: "微宽", en: "Slightly Wide" },
  "疏朗": { zh: "疏朗", en: "Loose" },
  "中文微排版": { zh: "中文微排版", en: "CJK Micro-typography" },
  "中西文相邻处自动加约 1/4 字宽间隙（盘古之白）并挤压行首行尾标点，符合 W3C 中文排版规范；只改版面不改文字，复制与搜索不受影响。": { zh: "中西文相邻处自动加约 1/4 字宽间隙（盘古之白）并挤压行首行尾标点，符合 W3C 中文排版规范；只改版面不改文字，复制与搜索不受影响。", en: "Adds ~1/4-em gaps between CJK and Latin text (pangu spacing) and trims line-edge punctuation per the W3C Chinese layout rules. Layout only — text stays untouched, so copy and search are unaffected." },
  "首字下沉": { zh: "首字下沉", en: "Drop Cap" },
  "杂志版式：正文首段首字放大并下沉两行，中英文均适用。": { zh: "杂志版式：正文首段首字放大并下沉两行，中英文均适用。", en: "Magazine style: enlarges and sinks the first letter of the opening paragraph by two lines. Works for Chinese and English." },
  "知更 · 本期": { zh: "知更 · 本期", en: "Robin · This Edition" },
  "封面故事": { zh: "封面故事", en: "Cover Story" },
