  "标题字体": { zh: "标题字体", en: "Title Font" },
  "跟随正文（默认）": { zh: "跟随正文（默认）", en: "Follow Body Font (Default)" },
  "得意黑（内置）": { zh: "得意黑（内置）", en: "Smiley Sans (Built-in)" },
  "标题、刊头独立选字；得意黑为内置开源斜体黑（OFL 授权），仅适合大标题，不适合正文。": { zh: "标题、刊头独立选字；得意黑为内置开源斜体黑（OFL 授权），仅适合大标题，不适合正文。", en: "Titles and the edition masthead use this font independently. Smiley Sans is a bundled open-source oblique sans (OFL licensed) — display only, not for body text." },
  "同题对比速读": { zh: "同题对比速读", en: "Multi-Source Compare" },
  "AI 速读": { zh: "AI 速读", en: "AI Brief" },
