  "同题报道至少需要两篇才能对比。": { zh: "同题报道至少需要两篇才能对比。", en: "At least two related articles are needed for a comparison." },
  "对比速读需要会员或每日 AI 额度。": { zh: "对比速读需要会员或每日 AI 额度。", en: "The comparison brief requires membership or daily AI quota." },
  "对照版式": { zh: "对照版式", en: "Bilingual Layout" },
  "逐句紧跟（默认）": { zh: "逐句紧跟（默认）", en: "Inline (Default)" },
  "对照分行（双语刊物式）": { zh: "对照分行（双语刊物式）", en: "Alternating Lines (Bilingual)" },
  "对照分行将原句独立成块，译文缩进悬挂其下，更接近双语刊物版式；逐句紧跟保持译文贴行显示。": { zh: "对照分行将原句独立成块，译文缩进悬挂其下，更接近双语刊物版式；逐句紧跟保持译文贴行显示。", en: "Alternating lines set each sentence apart with the translation hanging indented below — closer to a bilingual print layout; inline keeps translations flowing with the text." },
  "自定义样式": { zh: "自定义样式", en: "Custom CSS" },
  "注入自定义 CSS，实时生效并跨重启保持；供高级用户深度定制字体、间距与配色。": { zh: "注入自定义 CSS，实时生效并跨重启保持；供高级用户深度定制字体、间距与配色。", en: "Injects custom CSS that applies live and persists across restarts — for advanced users to fine-tune fonts, spacing, and colors." },
