  "聚焦模式：非当前段落渐暗（F）": { zh: "聚焦模式：非当前段落渐暗（F）", en: "Focus mode: dim non-current paragraphs (F)" },
  "聚焦模式：指针所在段落保持清晰，F 或再点按钮退出": { zh: "聚焦模式：指针所在段落保持清晰，F 或再点按钮退出", en: "Focus mode: the paragraph under the pointer stays clear. Press F or click again to exit." },
