  "同一篇文章按不同视角产出精读笔记：学者=结构化笔记、讲述者=故事化、评论员=批判审视、外行版=通俗类比、教练=行动清单、自定义=你的提示词。切换后重新点「一键精读」即按新风格重写。": { zh: "同一篇文章按不同视角产出精读笔记：学者=结构化笔记、讲述者=故事化、评论员=批判审视、外行版=通俗类比、教练=行动清单、自定义=你的提示词。切换后重新点「一键精读」即按新风格重写。", en: "One article, many lenses: Scholar=structured notes, Storyteller=narrative, Critic=critical review, Explainer=plain-language, Coach=action list, Custom=your own prompt. Re-run deep read to apply the new style." },
  "支持应用内直接更新：检查新版本 → 下载 → 静默安装重启。": { zh: "支持应用内直接更新：检查新版本 → 下载 → 静默安装重启。", en: "In-app updates: check, download, then silently install and restart." },
