  "已达免费版订阅上限": { zh: "已达免费版订阅上限", en: "Free Plan Feed Limit Reached" },
  "免费版最多订阅 30 个源，达上限后可清理不常读的源，或升级会员解除限制。": { zh: "免费版最多订阅 30 个源，达上限后可清理不常读的源，或升级会员解除限制。", en: "The free plan allows up to 30 feeds. Remove feeds you rarely read, or upgrade for unlimited." },
  "免费版最多订阅 30 个源。升级会员后可无限订阅，并可解锁不限量 AI 探索额度。": { zh: "免费版最多订阅 30 个源。升级会员后可无限订阅，并可解锁不限量 AI 探索额度。", en: "The free plan allows up to 30 feeds. Upgrade for unlimited feeds and unlimited AI discovery." },
  "今日 AI 额度已用完。升级会员可解锁不限量 AI 探索。": { zh: "今日 AI 额度已用完。升级会员可解锁不限量 AI 探索。", en: "Today’s AI quota is used up. Upgrade to unlock unlimited AI discovery." },
  "想深入哪个领域？留空 = 基于我的订阅": { zh: "想深入哪个领域？留空 = 基于我的订阅", en: "Which topics should we dig into? Leave blank to use your feeds" },
  "开始探索": { zh: "开始探索", en: "Start Discovering" },
  "基础版探索": { zh: "基础版探索", en: "Basic Discovery" },
  "探索风格": { zh: "探索风格", en: "Discovery Style" },
