  "订阅、文章与 AI 配置全部保存在本机，不经过任何第三方服务器。": { zh: "订阅、文章与 AI 配置全部保存在本机，不经过任何第三方服务器。", en: "Feeds, articles, and AI settings are all stored on this device — no third-party servers involved." },
