  "请前往“设置 -> 账号”启用本地或 FreshRSS 订阅账号。": { zh: "请前往“设置 -> 账号”启用本地或 FreshRSS 订阅账号。", en: "Go to Settings -> Accounts to enable a local or FreshRSS account." },
  "确认移除账号？": { zh: "确认移除账号？", en: "Remove This Account?" },
  "移除账号": { zh: "移除账号", en: "Remove Account" },
  "移除此账号将清除其在 RobinRead 本地同步的数据与凭据，但不会从 FreshRSS 服务器删除或退订您的 Feed。": { zh: "移除此账号将清除其在 RobinRead 本地同步的数据与凭据，但不会从 FreshRSS 服务器删除或退订您的 Feed。", en: "Removing this account clears its data and credentials stored locally in RobinRead. It does not delete or unsubscribe your feeds on the FreshRSS server." },
  "正在同步…": { zh: "正在同步…", en: "Syncing…" },
  "添加 FreshRSS 账号": { zh: "添加 FreshRSS 账号", en: "Add FreshRSS Account" },
