  "在 FreshRSS 网页「设置 → 账户 → API 管理」中开启 API 并生成应用专用密码。": { zh: "在 FreshRSS 网页「设置 → 账户 → API 管理」中开启 API 并生成应用专用密码。", en: "Enable the API and create an app password in the FreshRSS web UI under Settings → Account → API management." },
  "RobinRead 支持多账号并行与按需启用。本地订阅与 FreshRSS 远端订阅相互隔离，禁用账号不会删除本地数据或凭据。": { zh: "RobinRead 支持多账号并行与按需启用。本地订阅与 FreshRSS 远端订阅相互隔离，禁用账号不会删除本地数据或凭据。", en: "RobinRead supports multiple accounts, enabled as needed. Local and FreshRSS subscriptions stay isolated; disabling an account never deletes local data or credentials." },
  "服务商名称": { zh: "服务商名称", en: "Provider Name" },
  "Base URL（OpenAI 兼容）": { zh: "Base URL（OpenAI 兼容）", en: "Base URL (OpenAI-compatible)" },
  "可选模型（逗号分隔）": { zh: "可选模型（逗号分隔）", en: "Models (comma-separated)" },
  "可选模型（逗号分隔，第一个为当前使用）": { zh: "可选模型（逗号分隔，第一个为当前使用）", en: "Models (comma-separated; the first one is active)" },
  "可添加多个服务商并一键切换；API Key 只保存在这台设备。切换服务商后请填写对应的 API Key。": { zh: "可添加多个服务商并一键切换；API Key 只保存在这台设备。切换服务商后请填写对应的 API Key。", en: "Add multiple providers and switch instantly. API keys are stored on this device only. After switching, enter the matching API key." },
  "已设置（仅保存在这台设备）": { zh: "已设置（仅保存在这台设备）", en: "Configured (stored on this device only)" },
  "发送一条最小请求验证服务可用性。": { zh: "发送一条最小请求验证服务可用性。", en: "Sends a minimal request to verify the service works." },
