  "盯一个关键词，订阅源、AIHOT 热点与订阅源池的动态自动汇成一条专属信息流。": { zh: "盯一个关键词，订阅源、AIHOT 热点与订阅源池的动态自动汇成一条专属信息流。", en: "Pick a keyword and updates from your feeds, AIHOT and the source pool flow into one stream." },
