  "确定删除这份研究报告吗？此操作无法撤销。": { zh: "确定删除这份研究报告吗？此操作无法撤销。", en: "Delete this research report? This cannot be undone." },
  "未完成草稿：生成被取消，已收到的部分已保留。": { zh: "未完成草稿：生成被取消，已收到的部分已保留。", en: "Unfinished draft: generation was cancelled; what was generated has been kept." },
