  "已找到 %lld 条相关素材（未配置 AI，仅检索模式）": { zh: "已找到 %lld 条相关素材（未配置 AI，仅检索模式）", en: "Found %lld relevant sources (AI not configured — retrieval-only mode)" },
  "（无标题）": { zh: "（无标题）", en: "(untitled)" },
  "问点什么吧": { zh: "问点什么吧", en: "Ask something" },
