  "画像 Top %lld · 候选 %lld 篇": { zh: "画像 Top %lld · 候选 %lld 篇", en: "Top %lld profile words · %lld candidates" },
  "画像积累中 · 按新鲜度排序": { zh: "画像积累中 · 按新鲜度排序", en: "Profile building · sorted by freshness" },
  "你的阅读画像还在积累，当前按新鲜度排序；读得越多推荐越准。": { zh: "你的阅读画像还在积累，当前按新鲜度排序；读得越多推荐越准。", en: "Your reading profile is still building, so picks are sorted by freshness for now — the more you read, the smarter they get." },
