  "还没有文集。点上方「新建文集」，或在订阅源右键菜单里选择「加入文集 → 新建文集」。": { zh: "还没有文集。点上方「新建文集」，或在订阅源右键菜单里选择「加入文集 → 新建文集」。", en: "No books yet. Click New Book above, or right-click a feed and choose Add to Book → New Book." },
  "还没有订阅源，先添加订阅再建文集。": { zh: "还没有订阅源，先添加订阅再建文集。", en: "No feeds yet — add subscriptions before creating a book." },
