  "书目": { zh: "书目", en: "Books" },
  "删除文集只移除文集本身与自动目录里的成书；你手动导出到其他位置的书不受影响。": { zh: "删除文集只移除文集本身与自动目录里的成书；你手动导出到其他位置的书不受影响。", en: "Deleting a book removes the book itself and the EPUBs in its auto folder; books you exported elsewhere are untouched." },
