  "AI": { zh: "AI", en: "AI" },
  "AI 自动标签": { zh: "AI 自动标签", en: "AI Auto Tags" },
  "开启后每小时为最近入库、还没有标签的文章调用 AI 打 1-3 个标签（每批最多 20 篇）。新文章同时会继承订阅源的高频标签（不消耗 AI）。AI 与继承标签进入知识中心「标签」复核视图与图谱，不影响已有标签。": { zh: "开启后每小时为最近入库、还没有标签的文章调用 AI 打 1-3 个标签（每批最多 20 篇）。新文章同时会继承订阅源的高频标签（不消耗 AI）。AI 与继承标签进入知识中心「标签」复核视图与图谱，不影响已有标签。", en: "When on, AI tags the newest untagged articles with 1-3 tags every hour (up to 20 per batch). New articles also inherit their feed's frequent tags (no AI cost). AI and inherited tags appear in the Knowledge Center tag review and graph without touching existing tags." },
  "需要已配置 AI 服务商；未配置时静默跳过，不影响其他功能。": { zh: "需要已配置 AI 服务商；未配置时静默跳过，不影响其他功能。", en: "Requires a configured AI provider; silently skipped otherwise, nothing else is affected." },
