  "尚未配置 AI API Key：在 设置 → AI 功能 中配置后可用": { zh: "尚未配置 AI API Key：在 设置 → AI 功能 中配置后可用", en: "No AI API key configured — set it up in Settings → AI first" },
  "未配置转写端点：在 设置 → 转写 中开启并填写本地 ASR 服务地址": { zh: "未配置转写端点：在 设置 → 转写 中开启并填写本地 ASR 服务地址", en: "No transcription endpoint: enable it and add your local ASR URL in Settings → Transcription" },
  "音频转写": { zh: "音频转写", en: "Audio Transcription" },
  "在媒体中心为音频条目生成文字稿：可滚动阅读、按关键字全文检索、一键复制，并可用 AI 生成摘要。": { zh: "在媒体中心为音频条目生成文字稿：可滚动阅读、按关键字全文检索、一键复制，并可用 AI 生成摘要。", en: "Generate transcripts for audio items in Media: scrollable reading, full-text keyword search, one-click copy, plus AI summaries." },
  "开启音频转写": { zh: "开启音频转写", en: "Enable transcription" },
  "默认关闭：开启后才会在媒体视图显示「转写」按钮。": { zh: "默认关闭：开启后才会在媒体视图显示「转写」按钮。", en: "Off by default: the Transcribe button appears in Media only after you enable it." },
  "转写端点": { zh: "转写端点", en: "Transcription endpoint" },
  "OpenAI 兼容 /v1/audio/transcriptions 完整地址（本地 whisper.cpp server / faster-whisper-server 等）。": { zh: "OpenAI 兼容 /v1/audio/transcriptions 完整地址（本地 whisper.cpp server / faster-whisper-server 等）。", en: "Full OpenAI-compatible /v1/audio/transcriptions URL (local whisper.cpp server, faster-whisper-server, etc.)." },
  "转写 API Key（可选）": { zh: "转写 API Key（可选）", en: "Transcription API key (optional)" },
  "本地服务通常留空；仅端点要求鉴权时填写。经系统加密保存，不随文字稿外发。": { zh: "本地服务通常留空；仅端点要求鉴权时填写。经系统加密保存，不随文字稿外发。", en: "Leave empty for local servers; only fill in if your endpoint requires auth. Stored OS-encrypted, never sent with transcripts." },
  "转写模型名": { zh: "转写模型名", en: "Transcription model" },
  "请求体 model 字段（whisper-1 / large-v3 等，按你的服务填写）。": { zh: "请求体 model 字段（whisper-1 / large-v3 等，按你的服务填写）。", en: "The model field in the request body (whisper-1 / large-v3 etc., per your service)." },
  "工作方式": { zh: "工作方式", en: "How it works" },
  "离线优先": { zh: "离线优先", en: "Offline first" },
  "已离线下载的音频直接读本地文件；未离线的按需临时下载（≤500MB），转写完即删。": { zh: "已离线下载的音频直接读本地文件；未离线的按需临时下载（≤500MB），转写完即删。", en: "Downloaded audio is read from disk; otherwise it is fetched temporarily (≤500MB) and deleted after transcription." },
  "单飞排队": { zh: "单飞排队", en: "One at a time" },
  "同一时刻只跑一个转写任务，其余自动排队；失败可一键重试。": { zh: "同一时刻只跑一个转写任务，其余自动排队；失败可一键重试。", en: "Only one transcription runs at a time; the rest queue up. Failures can be retried with one click." },
  "仅支持为音频条目转写文字稿。": { zh: "仅支持为音频条目转写文字稿。", en: "Only audio items can be transcribed." },
  "尚未配置转写端点：请在设置 → 转写中开启并填写 OpenAI 兼容端点。": { zh: "尚未配置转写端点：请在设置 → 转写中开启并填写 OpenAI 兼容端点。", en: "No transcription endpoint configured: enable it and fill in an OpenAI-compatible URL in Settings → Transcription." },
  "转写端点必须是 http(s) 地址。": { zh: "转写端点必须是 http(s) 地址。", en: "The transcription endpoint must be an http(s) URL." },
  "仅支持转写 http(s) 链接的媒体。": { zh: "仅支持转写 http(s) 链接的媒体。", en: "Only http(s) media links can be transcribed." },
