  "把上周阅读编成一期周刊：AI 导语 + 主题归纳 + 金句摘录": { zh: "把上周阅读编成一期周刊：AI 导语 + 主题归纳 + 金句摘录", en: "Compose last week's reading into an issue: AI intro + topic digest + quotes" },
