  "给一个学习目标，AI 从订阅库排出 7 或 14 天课程。": { zh: "给一个学习目标，AI 从订阅库排出 7 或 14 天课程。", en: "Give a learning goal and AI arranges a 7- or 14-day course from your feeds." },
