  "从不翻译": { zh: "从不翻译", en: "Never Translate" },
  "此源文章不再自动翻译": { zh: "此源文章不再自动翻译", en: "Articles from this feed will no longer be auto-translated" },
  "已开启：变更快照自动进存档馆": { zh: "已开启：变更快照自动进存档馆", en: "On: change snapshots go to the Archive Hall automatically" },
  "已关闭自动存档": { zh: "已关闭自动存档", en: "Auto-archiving turned off" },
