  "恢复跟随全局": { zh: "恢复跟随全局", en: "Reset to Global" },
  "还没有任何存档": { zh: "还没有任何存档", en: "No archives yet" },
  "最近": { zh: "最近", en: "Recent" },
  "紧凑模式隐藏摘要，仅显示标题行；宽松模式加大行距与留白。": { zh: "紧凑模式隐藏摘要，仅显示标题行；宽松模式加大行距与留白。", en: "Compact hides summaries and shows titles only; Relaxed adds line height and breathing room." },
  "清理中…": { zh: "清理中…", en: "Cleaning up…" },
  "存储与历史记录": { zh: "存储与历史记录", en: "Storage & History" },
  "按保留期限自动淘汰超期的已读文章（以拉取时间计）；未读、收藏与稍后读永远保留，源站刷新也不会把清理过的文章重新灌回。": { zh: "按保留期限自动淘汰超期的已读文章（以拉取时间计）；未读、收藏与稍后读永远保留，源站刷新也不会把清理过的文章重新灌回。", en: "Read articles past the retention window are removed automatically (by fetch time); unread, starred and read-later items are always kept, and refreshing won't re-import cleaned articles." },
  "历史文章保留期限": { zh: "历史文章保留期限", en: "Article Retention" },
  "默认永久保留。开启后每次刷新自动清理超期已读。": { zh: "默认永久保留。开启后每次刷新自动清理超期已读。", en: "Keep forever by default. When enabled, expired read articles are cleaned on every refresh." },
  "永久保留": { zh: "永久保留", en: "Keep Forever" },
  "保留 180 天": { zh: "保留 180 天", en: "Keep 180 Days" },
  "保留 1 年": { zh: "保留 1 年", en: "Keep 1 Year" },
  "保留 2 年": { zh: "保留 2 年", en: "Keep 2 Years" },
  "回收磁盘空间": { zh: "回收磁盘空间", en: "Reclaim Disk Space" },
  "清理历史文章后立即压缩数据库并归还磁盘空间。": { zh: "清理历史文章后立即压缩数据库并归还磁盘空间。", en: "Compact the database right after cleaning to return disk space." },
  "每日自动备份": { zh: "每日自动备份", en: "Daily Auto Backup" },
  "默认开启。备份写入本地 backups 目录，不含 API Key。": { zh: "默认开启。备份写入本地 backups 目录，不含 API Key。", en: "On by default. Backups are written to the local backups folder and never include API keys." },
  "立即创建一份备份，或打开备份文件夹查看/恢复。": { zh: "立即创建一份备份，或打开备份文件夹查看/恢复。", en: "Create a backup now, or open the backups folder to browse or restore." },
  "%lld:00 · %lld 次": { zh: "%lld:00 · %lld 次", en: "%lld:00 · %lld times" },
  "严谨学者（默认）": { zh: "严谨学者（默认）", en: "Rigorous Scholar (Default)" },
  "「听文章」使用的高品质语音。神经语音免费需联网；自定义服务支持情感模型与音色克隆。": { zh: "「听文章」使用的高品质语音。神经语音免费需联网；自定义服务支持情感模型与音色克隆。", en: "High-quality voices for Read Aloud. Neural voices are free but online; custom services support emotion models and voice cloning." },
  "神经语音：微软 Neural 音色（晓晓/云希等），自然接近真人，需联网；本地语音：系统离线语音；自定义 TTS：任何 OpenAI 兼容 /v1/audio/speech 服务或局域网语音服务（如 CosyVoice）。": { zh: "神经语音：微软 Neural 音色（晓晓/云希等），自然接近真人，需联网；本地语音：系统离线语音；自定义 TTS：任何 OpenAI 兼容 /v1/audio/speech 服务或局域网语音服务（如 CosyVoice）。", en: "Neural: Microsoft Neural voices (Xiaoxiao, Yunxi, …), near-human and online; Local: offline system voices; Custom TTS: any OpenAI-compatible /v1/audio/speech endpoint or LAN voice service (e.g. CosyVoice)." },
  "晓晓温暖自然、云希阳光、云健磁性、云扬新闻腔；自定义引擎时此音色作 voice 参数。": { zh: "晓晓温暖自然、云希阳光、云健磁性、云扬新闻腔；自定义引擎时此音色作 voice 参数。", en: "Xiaoxiao warm, Yunxi sunny, Yunjian deep, Yunyang newsy; with a custom engine this is passed as the voice parameter." },
  "自定义端点": { zh: "自定义端点", en: "Custom Endpoint" },
  "例如 https://api.openai.com/v1/audio/speech，或局域网语音服务地址（如 CosyVoice / GPT-SoVITS）。": { zh: "例如 https://api.openai.com/v1/audio/speech，或局域网语音服务地址（如 CosyVoice / GPT-SoVITS）。", en: "e.g. https://api.openai.com/v1/audio/speech, or a LAN voice service (CosyVoice / GPT-SoVITS)." },
  "模型与音色": { zh: "模型与音色", en: "Model & Voice" },
  "model 与 voice 参数（OpenAI 兼容格式），如 tts-1 / alloy；留空用服务端默认。": { zh: "model 与 voice 参数（OpenAI 兼容格式），如 tts-1 / alloy；留空用服务端默认。", en: "model and voice parameters (OpenAI-compatible), e.g. tts-1 / alloy; leave empty for server defaults." },
  "自定义服务的鉴权密钥（Bearer），不出本机；本地服务可留空。": { zh: "自定义服务的鉴权密钥（Bearer），不出本机；本地服务可留空。", en: "Auth key (Bearer) for the custom service — never leaves this machine; leave empty for local services." },
  "已切换到「": { zh: "已切换到「", en: "Switched to \"" },
  "「": { zh: "「", en: "\"" },
