  "对服务器根目录发起一次真实探测，验证地址与凭据。": { zh: "对服务器根目录发起一次真实探测，验证地址与凭据。", en: "Probe the server root once to verify the address and credentials." },
  "本地服务通常留空；仅端点要求鉴权时填写。经系统加密（DPAPI）保存，不随文字稿外发；留空提交不改动已存 Key。": { zh: "本地服务通常留空；仅端点要求鉴权时填写。经系统加密（DPAPI）保存，不随文字稿外发；留空提交不改动已存 Key。", en: "Leave empty for local services; fill in only if the endpoint requires auth. Stored encrypted (DPAPI) and never sent with transcripts; submitting empty keeps the stored key." },
  "已保存——输入新值可替换": { zh: "已保存——输入新值可替换", en: "Saved — type a new value to replace it" },
  "一键起服务，手机扫码读轻量 Web 版：文章列表、正文阅读与「标为已读」回传。零云零账号，数据始终在你的设备之间。": { zh: "一键起服务，手机扫码读轻量 Web 版：文章列表、正文阅读与「标为已读」回传。零云零账号，数据始终在你的设备之间。", en: "Start a service and scan the QR code to read a lightweight web version: article list, full text and read-state sync back. No cloud, no account — data stays between your devices." },
